<?php get_header(); ?><div class="container py-5"><?php while(have_posts()):the_post(); ?><article <?php post_class(); ?>><h1><?php the_title(); ?></h1><div class="entry-content"><?php if(wp_attachment_is_image()) echo wp_get_attachment_image(get_the_ID(),'full',['class'=>'img-fluid']); else the_content(); ?></div></article><?php endwhile; ?></div><?php get_footer(); ?>
